class Solution {
    private final Random rand = new Random();

    public int findKthLargest(int[] nums, int k) {
        int target = nums.length - k;               // 第 k 大 = 升序下标 n-k
        int lo = 0, hi = nums.length - 1;
        while (true) {
            int pivot = nums[lo + rand.nextInt(hi - lo + 1)];
            int lt = lo, i = lo, gt = hi;           // [lo,lt) 小于  [lt,i) 等于  (gt,hi] 大于
            while (i <= gt) {
                if (nums[i] < pivot) {
                    swap(nums, lt++, i++);
                } else if (nums[i] > pivot) {
                    swap(nums, i, gt--);            // 换过来的数还没看过，i 不动
                } else {
                    i++;
                }
            }
            if (target < lt) {
                hi = lt - 1;                        // 答案在小于区
            } else if (target > gt) {
                lo = gt + 1;                        // 答案在大于区
            } else {
                return pivot;                       // 落在等于区，就是 pivot
            }
        }
    }

    private void swap(int[] a, int i, int j) {
        int t = a[i]; a[i] = a[j]; a[j] = t;
    }
}

