class Solution {
    public int findKthLargest(int[] nums, int k) {
        PriorityQueue<Integer> heap = new PriorityQueue<>();    // 小顶堆
        for (int i = 0; i < k; i++) heap.offer(nums[i]);       // 先放前 k 个
        for (int i = k; i < nums.length; i++) {
            if (nums[i] > heap.peek()) {                        // 比堆顶大，才有资格进前 k
                heap.poll();
                heap.offer(nums[i]);
            }
        }
        return heap.peek();
    }
}

